-- Attorney sign-off: "the human review step before a chronology leaves
-- draft status. Nothing generated by an agent is considered final without
-- it." (CLAUDE.md). Tracked at the case level since sign-off covers the
-- whole chronology, not individual entries.
alter table cases add column chronology_signed_off boolean not null default false;
alter table cases add column chronology_signed_off_at timestamptz;
